previewCss:
.darma-loader-gyroscope {
  position: relative;
  width: 48px;
  height: 48px;
}
.darma-loader-gyroscope i {
  position: absolute;
  border-radius: 50%;
  border: 3px solid var(--loader-color, #6366f1);
  box-sizing: border-box;
}
.darma-loader-gyroscope i:nth-child(1) { inset: 0; animation: darma-loader-gyroscope-g1 1.4s linear infinite; }
.darma-loader-gyroscope i:nth-child(2) { inset: 6px; border-color: #818cf8; animation: darma-loader-gyroscope-g2 1.4s linear infinite; }
.darma-loader-gyroscope i:nth-child(3) { inset: 12px; animation: darma-loader-gyroscope-g3 1.4s linear infinite; }
@keyframes darma-loader-gyroscope-g1 {
  0%, 100% { transform: rotate(0deg) scaleX(1); }
  50% { transform: rotate(180deg) scaleX(0.2); }
}
@keyframes darma-loader-gyroscope-g2 {
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(0.2); }
}
@keyframes darma-loader-gyroscope-g3 {
  0%, 100% { transform: scaleX(1) rotate(0deg); }
  50% { transform: scaleX(0.2) rotate(-180deg); }
}

